	shouldPersist;
	constructor(db, sanitizer, options = {}) {
		super(db, options.operationModel ?? "operationLogs", "createdAt", [
			"module",
			"action",
			"userId",
			"status"
		], sanitizer);
		this.shouldPersist = options.operationShouldPersist;
	}
	async log(input) {
		if (this.shouldPersist) {
			try {
				if (await this.shouldPersist(input) === false) return;
			} catch {}
		};
		await this.write(() => ({
			module: input.module,
			action: input.action,
			userId: input.userId,
			targetId: input.targetId,
			targetType: input.targetType,
			method: input.method,
			path: input.path ? this.sanitizer.sanitizeText(input.path) : input.path,
			ipAddress: input.ipAddress,
			userAgent: input.userAgent ? this.sanitizer.sanitizeText(input.userAgent) : input.userAgent,
			status: input.status || "SUCCESS",
			duration: input.duration,
			errorMessage: input.errorMessage == null ? undefined : this.sanitizer.sanitizeText(input.errorMessage),
			requestData: this.sanitizer.sanitizeValue(input.requestData),
			responseData: this.sanitizer.sanitizeValue(input.responseData),
			metadata: this.sanitizer.sanitizeValue(input.metadata)
		}));
	}
	async getModuleStatistics(module) {
		const [total, successCount, failedCount, avgDuration, actionStats] = await Promise.all([
			this.model.count({ where: { module } }),
			this.model.count({ where: {
				module,
				status: "SUCCESS"
			} }),
			this.model.count({ where: {
				module,
				status: "FAILED"
			} }),
			this.average(module, "duration"),
			this.actionStatistics(module)
		]);
		return {
			module,
			total,
			successCount,
			failedCount,
			successRate: total ? (successCount / total * 100).toFixed(2) : "0",
			avgDuration,
			actionStats
		};
	}
	exportToCsv(params) {
		return this.csv(params, [
			["id", "ID"],
			["module", "模块"],
			["action", "操作"],
			["userId", "用户ID"],
			["targetId", "目标ID"],
			["targetType", "目标类型"],
			["method", "HTTP方法"],
			["path", "路径"],
			["ipAddress", "IP地址"],
			["status", "状态"],
			["duration", "耗时(ms)"],
			["errorMessage", "错误信息"],
			["createdAt", "创建时间"]
		]);
	}
}

